</template>
  
  <script>
  import gsap from 'gsap'
  import {
    onMounted,
    nextTick,
    onUnmounted,
    ref
} from 'vue';

  export default {
    name: 'ReliquaryWidget',
    setup() {
      var reliquaryOutlineTl = gsap.timeline();
      var isUnmounted = false

      onMounted(async () => {
        await nextTick();
        // Define variables for the timelines
        var topPaths = document.querySelectorAll('.reliquarywidget .glasser .top-banner svg path');
        var midContent = document.querySelectorAll('.reliquarywidget .glasser .mid-display svg path:not(.outline):not(.line-stroke):not(.fake-text):not(.after-dot)');
        var midStroke = document.querySelectorAll('.reliquarywidget .glasser .mid-display svg path.line-stroke');
        var midFakeText = document.querySelectorAll('.fake-text');
        var midAfterDot = document.querySelectorAll('.after-dot');
        var midBackDot = document.querySelectorAll('.back-dots path');
        var midSmallDot = document.querySelectorAll('.side-dot-sm');
       
        //  This is the top animation
        function animatePathRandReliquary(path) {
          if (isUnmounted) return;
          if(path){
              gsap.to(path, {
                duration: 1, // Random duration between 0.3 - 0.8s
                opacity: () => Math.random() > 0.5 ? 0 : 1, // Randomly make it disappear or appear
                ease: "power1.inOut",
                stagger: 0.1,
                onComplete: () => {
                setTimeout(() => animatePathRandReliquary(path), Math.random() * 1000);
                }
              });
          }
        };
        topPaths.forEach(path => {
         setTimeout(()=> animatePathRandReliquary(path), Math.random()*1000);
        });
        // End top anim

        // define fake text anim function
        function animateFakeText(path) {
          if (isUnmounted) return;
          reliquaryOutlineTl.to(path, {
            duration: .3, 
            opacity: () => Math.random() > 0.5 ? 0.5 : 1,
            stagger: 0.2,
            onComplete: () => {
              setTimeout(() => animateFakeText(path), 1000);
            }
          })
        }
        function animateBarGraph(barSelector) {
          if (isUnmounted) return;
          if(barSelector) {
            gsap.to(barSelector, {
              duration: 0.8, // Random duration between 0.3 - 0.8s
              width: (Math.floor(Math.random() * (68 - 54 + 1)) + 54) + '%', // Randomly make it disappear or appear
              ease: "power1.inOut",
              stagger: 0.3,
              onComplete: () => {
                setTimeout(() => animateBarGraph(barSelector), Math.random() * 100);
              }
            });
          }
        }

        // begin mid anim
        reliquaryOutlineTl.set('#maskRect-main', {
          width: "0%",
        })
        reliquaryOutlineTl.set('#maskRect-minor', {
          width: "0%",
        })
        reliquaryOutlineTl.set('#maskRect-bar-one', {
          width: "0%",
        })
        reliquaryOutlineTl.set('#maskRect-bar-two', {
          width: "0%",
        })
        reliquaryOutlineTl.set('#maskRect-bar-three', {
          width: "0%",
        })
        reliquaryOutlineTl.set('#maskRect-bar-four', {
          width: "0%",
        })
        reliquaryOutlineTl.set(midContent, {
          opacity: 0
        })
        reliquaryOutlineTl.set(midFakeText, {
          opacity: 0
        })
        reliquaryOutlineTl.set(midAfterDot, {
          opacity: 0
        })
        let length1 = midStroke[0].getTotalLength();
        reliquaryOutlineTl.set(midStroke[0], {
          strokeDasharray: length1, 
          strokeDashoffset: -length1
        })
        let length2 = midStroke[1].getTotalLength();
        reliquaryOutlineTl.set(midStroke[1], {
          strokeDasharray: length2, 
          strokeDashoffset: length2
        })
       
        reliquaryOutlineTl.to('#maskRect-main', {
          width: "100%",
          duration: 1,
          ease: 'linear',
          delay: 0.5,
          onComplete: () => {
            reliquaryOutlineTl.to(midContent, {
              opacity: 1,
              duration: 1,
              ease: 'linear',
              onComplete: () => {
                reliquaryOutlineTl.to(midStroke, { 
                  strokeDashoffset: 0, 
                  duration: 1, 
                  ease: "power2.out",
                  onComplete: () => {
                    gsap.to(midAfterDot, {
                      opacity: 1,
                      duration: 0.3,
                      onComplete: () => {
                        reliquaryOutlineTl.to('#maskRect-minor', {
                          width: "100%",
                          duration: 1,
                          ease: 'linear',
                        })
                      }
                    })
                    gsap.to(midFakeText, {
                      opacity: 1,
                      duration: 0.3,
                      onComplete: () => {
                        animateFakeText(document.querySelectorAll('.fake-text path'));
                      }
                    })
                    setTimeout(animatePathRandReliquary(midBackDot), Math.random() * 1000);

                    setTimeout(animateBarGraph('#maskRect-bar-one'), Math.random() * 1000);
                    setTimeout(animateBarGraph('#maskRect-bar-two'), Math.random() * 1000);
                    setTimeout(animateBarGraph('#maskRect-bar-three'), Math.random() * 1000);
                    setTimeout(animateBarGraph('#maskRect-bar-four'), Math.random() * 1000);
                  }
                })
              }
            })
          }
        })
        // End mid anim

        // Begin bottom anim
        var graphBars = document.querySelectorAll('.reliquarywidget .glasser .bottom-icons svg path');
        var reliquaryChartTl = gsap.timeline();

        function animateWavegraphOne(bar) {
          if (isUnmounted) return;
          // let tempLength = bar.getTotalLength();
          if(bar) {
            gsap.to(bar, {
              duration: 1.4,
              opacity: Math.random() > .5 ? 0:1,
              onComplete: () => {
                setTimeout(animateWavegraphTwo(bar), Math.random() * 1000);
              }
            })
          } 
        }
        function animateWavegraphTwo(bar) {
          if (isUnmounted) return;
          if(bar){
            let tempLength = bar.getTotalLength();

            gsap.to(bar, {
              duration: 1.4,
              opacity: Math.random() > .5 ? 0:1,
              onComplete: () => {
                setTimeout(animateWavegraphOne(bar), Math.random() * 1000);
              }
            })
          }
        }

        graphBars.forEach(bar => {
          let length = bar.getTotalLength();
          reliquaryChartTl.set(bar, {
            strokeDasharray: length, 
            strokeDashoffset: -length
          })
        })
        reliquaryChartTl.to(graphBars, { 
                  strokeDashoffset: 0, 
                  duration: 1, 
                  ease: "power2.out",
                  onComplete: () => {
                    graphBars.forEach(bar => {
                      setTimeout(animateWavegraphOne(bar), Math.random() * 1000);
                    })
                  }
        })

      });
      onUnmounted(async () => {
        console.log(2419, 'unmount is called');
        isUnmounted = true;
      })
    }
  };
  </script>
  
  <style scoped>
    .reliquarywidget {
      position: relative;
        width: 100%;
        height: auto;
        max-width: 260px;
        max-height: 300px;
    }
    .reliquarywidget svg {
        width: 100%;
        height: auto;
        max-width: 300px;
    }
    .top-banner, 
    .mid-display, 
    .bottom-icons {
        width: 100%;
        height: auto;
        display: block;
    }
    .bottom-icons {
        display: flex;
        justify-items: center;
        justify-content: center;
    }
    .glasser {
      cursor: pointer;
    }
    /* Frosted Glass Effect */
    .glasser::before {
        content: "";
        position: absolute;
        top: 50%;
        left: 0;
        width: 100%;
        height: 100%;
        transform: translateY(-50%);
        border-radius: 10px;
        background: rgba(0, 0, 0, 0, 0.25);
        backdrop-filter: blur(2px);
        opacity: 0;
        transition: opacity 0.6s ease-in-out;
    }

    /* Label Text */
    .glasser::after {
        content: "Reliquary";
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        font-size: 1.5rem;
        color: #fff;
        font-weight: bold;
        text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8);
        opacity: 0;
        transition: opacity 0.8s ease-in-out;
    }

    /* Hover Effect */
    .glasser:hover::before,
    .glasser:hover::after {
        opacity: 1;
    }
  </style>
  